import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import axios from 'axios';

const API = 'http://localhost:5000/api';

// 원고지 200자 기준 분량 계산 (한글 1자 = 1칸, 공백 = 1칸, 영문/숫자 = 0.5칸으로 근사)
function calcManuscriptVolume(text) {
  if (!text) return 0;
  let count = 0;
  for (const char of text) {
    if (/[\u3131-\uD7AF]/.test(char)) {
      count += 1; // 한글
    } else if (/[a-zA-Z0-9]/.test(char)) {
      count += 0.5; // 영문/숫자
    } else if (char === ' ') {
      count += 1; // 공백
    } else if (char === '\n') {
      count += 0; // 줄바꿈은 제외
    } else {
      count += 1; // 특수문자 등
    }
  }
  // 원고지 200자 기준 분량 = 총 글자수 / 200
  return Math.round((count / 200) * 10) / 10;
}

function ArticleWrite() {
  const { sectionId } = useParams();
  const { user, showToast } = useAuth();
  const navigate = useNavigate();

  const [article, setArticle] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  // 입력 상태
  const [title, setTitle] = useState('');
  const [subtitle, setSubtitle] = useState('');
  const [body, setBody] = useState('');
  const [caption1, setCaption1] = useState('');
  const [caption2, setCaption2] = useState('');
  const [reporterName, setReporterName] = useState('');
  const [reporterEmail, setReporterEmail] = useState('');
  const [photo1Preview, setPhoto1Preview] = useState(null);
  const [photo2Preview, setPhoto2Preview] = useState(null);

  // 컨펌 도구 상태
  const [activeTool, setActiveTool] = useState(null); // 'strike' or 'add'
  const titleRef = useRef(null);
  const subtitleRef = useRef(null);
  const bodyRef = useRef(null);
  const caption1Ref = useRef(null);
  const caption2Ref = useRef(null);

  // 실시간 글자수 계산을 위한 별도 state (에디터 리렌더링 방지)
  const [counts, setCounts] = useState({
    title: 0,
    subtitle: 0,
    body: 0,
  });

  const isAdmin = user?.role === 'admin';

  useEffect(() => {
    if (!user || !['admin', 'reporter'].includes(user.role)) {
      navigate('/');
      return;
    }
    fetchArticle();
  }, [user, sectionId]);

  const fetchArticle = async () => {
    try {
      const token = localStorage.getItem('dju_token');
      const res = await axios.get(`${API}/articles/section/${sectionId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      const a = res.data.article;
      setArticle(a);
      
      // 초기 값 설정
      setReporterName(a.reporter_name || user.name || '');
      setReporterEmail(a.reporter_email || user.email || '');
      
      // 글자수 초기화
      setCounts({
        title: stripHtml(a.title || '').length,
        subtitle: stripHtml(a.subtitle || '').length,
        body: calcManuscriptVolume(stripHtml(a.body || '')),
      });

      if (a.photo1_url) setPhoto1Preview(`http://localhost:5000${a.photo1_url}`);
      if (a.photo2_url) setPhoto2Preview(`http://localhost:5000${a.photo2_url}`);
    } catch (err) {
      showToast(err.response?.data?.message || '기사를 불러올 수 없습니다.', 'error');
      navigate(-1);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    // contentEditable의 HTML 내용을 직접 가져옴
    const currentTitle = titleRef.current?.innerHTML || '';
    const currentSubtitle = subtitleRef.current?.innerHTML || '';
    const currentBody = bodyRef.current?.innerHTML || '';
    const currentCaption1 = caption1Ref.current?.innerHTML || '';
    const currentCaption2 = caption2Ref.current?.innerHTML || '';

    try {
      const token = localStorage.getItem('dju_token');
      await axios.put(`${API}/articles/${article.id}`, {
        title: currentTitle,
        subtitle: currentSubtitle,
        body: currentBody,
        caption1: currentCaption1,
        caption2: currentCaption2,
        reporter_name: reporterName,
        reporter_email: reporterEmail,
      }, { headers: { Authorization: `Bearer ${token}` } });
      showToast('기사가 저장되었습니다.', 'success');
      fetchArticle();
    } catch (err) {
      showToast(err.response?.data?.message || '저장에 실패했습니다.', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handlePhotoUpload = async (e, slot) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('photo', file);
    formData.append('slot', slot);

    try {
      const token = localStorage.getItem('dju_token');
      const res = await axios.post(`${API}/articles/${article.id}/upload`, formData, {
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'multipart/form-data' }
      });
      const url = `http://localhost:5000${res.data.url}`;
      if (slot === 'photo1') setPhoto1Preview(url);
      else setPhoto2Preview(url);
      showToast('사진이 업로드되었습니다.', 'success');
    } catch (err) {
      showToast('사진 업로드에 실패했습니다.', 'error');
    }
  };

  const handleSubmitConfirm = async () => {
    // 먼저 저장
    setSaving(true);
    const currentTitle = titleRef.current?.innerHTML || '';
    const currentSubtitle = subtitleRef.current?.innerHTML || '';
    const currentBody = bodyRef.current?.innerHTML || '';
    const currentCaption1 = caption1Ref.current?.innerHTML || '';
    const currentCaption2 = caption2Ref.current?.innerHTML || '';

    try {
      const token = localStorage.getItem('dju_token');
      await axios.put(`${API}/articles/${article.id}`, {
        title: currentTitle,
        subtitle: currentSubtitle,
        body: currentBody,
        caption1: currentCaption1,
        caption2: currentCaption2,
        reporter_name: reporterName,
        reporter_email: reporterEmail,
      }, { headers: { Authorization: `Bearer ${token}` } });
    } catch (err) {
      showToast('저장에 실패했습니다.', 'error');
      setSaving(false);
      return;
    }
    setSaving(false);

    // 컨펌 요청
    setSubmitting(true);
    try {
      const token = localStorage.getItem('dju_token');
      await axios.put(`${API}/articles/${article.id}/submit`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      showToast('편집장 컨펌 요청이 완료되었습니다!', 'success');
      fetchArticle();
    } catch (err) {
      showToast(err.response?.data?.message || '컨펌 요청에 실패했습니다.', 'error');
    } finally {
      setSubmitting(false);
    }
  };

  // 도구 버튼 클릭 핸들러
  const applyTool = (tool) => {
    if (!isAdmin) return;
    
    const selection = window.getSelection();
    if (!selection.rangeCount) return;
    
    if (tool === 'strike') {
      const range = selection.getRangeAt(0);
      if (range.collapsed) return;
      const span = document.createElement('span');
      span.style.color = 'red';
      span.style.textDecoration = 'line-through';
      span.appendChild(range.extractContents());
      range.insertNode(span);
    } else if (tool === 'add') {
      // 추가 모드 토글
      const newMode = activeTool === 'add' ? null : 'add';
      setActiveTool(newMode);
      
      // 추가 모드가 켜질 때 파란색 서식 적용 시작
      if (newMode === 'add') {
        document.execCommand('foreColor', false, 'blue');
      } else {
        // 꺼질 때 기본색(검정)으로 복구
        document.execCommand('foreColor', false, 'black');
      }
    }
  };

  // 입력 시 추가 모드 처리 및 글자수 업데이트
  const handleInput = (e, type) => {
    const html = e.currentTarget.innerHTML;
    const plainText = stripHtml(html);
    
    if (type === 'title') setCounts(prev => ({ ...prev, title: plainText.length }));
    if (type === 'subtitle') setCounts(prev => ({ ...prev, subtitle: plainText.length }));
    if (type === 'body') setCounts(prev => ({ ...prev, body: calcManuscriptVolume(plainText) }));
    
    // activeTool === 'add' 인 경우 execCommand('foreColor')가 이미 동작 중임
  };

  if (loading) {
    return (
      <main className="max-w-4xl mx-auto px-6 py-20 text-center text-gray-400">
        <i className="fas fa-spinner fa-spin text-3xl mb-4"></i>
        <p>불러오는 중...</p>
      </main>
    );
  }

  if (!article) return null;

  const sec = article; // article 객체에 section 정보도 포함되어 있음
  const isHancutDaejin = sec.section_key === '4면한컷대진';
  
  // HTML 태그 제거 후 텍스트만 추출하여 분량 계산
  const stripHtml = (html) => {
    const tmp = document.createElement("DIV");
    tmp.innerHTML = html;
    return tmp.textContent || tmp.innerText || "";
  };

  const currentVolume = counts.body;
  const volumeDiff = sec.volume ? (currentVolume - sec.volume) : 0;
  const isAlreadySubmitted = article.status === 'submitted' || article.status === 'confirmed';

  // 제목/부제목 글자수 (HTML 제외)
  const titleLen = counts.title;
  const titleOverMax = sec.title_max_length && titleLen > sec.title_max_length;
  const titleUnderMin = sec.title_min_length && titleLen < sec.title_min_length && titleLen > 0;

  const subtitleLen = counts.subtitle;
  const subtitleOverMax = sec.subtitle_max_length && subtitleLen > sec.subtitle_max_length;
  const subtitleUnderMin = sec.subtitle_min_length && subtitleLen < sec.subtitle_min_length && subtitleLen > 0;

  return (
    <main className="max-w-4xl mx-auto px-6 py-8">
      {/* 편집 도구 바 (관리자 전용) */}
      {isAdmin && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-50 bg-white shadow-2xl rounded-full px-6 py-3 border border-gray-200 flex items-center space-x-4 animate-bounce-in">
          <span className="text-xs font-bold text-gray-400 mr-2 uppercase tracking-widest">Editor Tools</span>
          <button
            onClick={() => applyTool('strike')}
            className="w-10 h-10 rounded-full flex items-center justify-center bg-red-50 text-red-600 hover:bg-red-100 transition shadow-sm"
            title="삭선 도구 (드래그 후 클릭)"
          >
            <i className="fas fa-strikethrough"></i>
          </button>
          <button
            onClick={() => applyTool('add')}
            className={`w-10 h-10 rounded-full flex items-center justify-center transition shadow-sm ${
              activeTool === 'add' ? 'bg-blue-600 text-white' : 'bg-blue-50 text-blue-600 hover:bg-blue-100'
            }`}
            title="追加 도구 (입력 시 파란색)"
          >
            <i className="fas fa-plus"></i>
          </button>
          <div className="h-6 w-px bg-gray-200"></div>
          <button
            onClick={() => document.execCommand('removeFormat')}
            className="w-10 h-10 rounded-full flex items-center justify-center bg-gray-50 text-gray-600 hover:bg-gray-100 transition shadow-sm"
            title="서식 지우기"
          >
            <i className="fas fa-eraser"></i>
          </button>
        </div>
      )}

      {/* 뒤로가기 */}
      <button
        onClick={() => navigate(-1)}
        className="text-gray-400 hover:text-[#004b93] mb-6 flex items-center space-x-2 transition"
      >
        <i className="fas fa-arrow-left"></i>
        <span className="font-semibold">지면 현황으로 돌아가기</span>
      </button>

      {/* 제목 헤더 */}
      <div className="bg-[#004b93] text-white rounded-3xl p-8 mb-8">
        <h1 className="text-2xl font-extrabold mb-2">
          {sec.section_name} 담당자 {sec.assigned_reporter_name || user.name} 기자
        </h1>
        <p className="text-blue-200 text-sm">
          {sec.volume && `원고 분량: 원고지 200자 기준 ${sec.volume}`}
          {sec.title_max_length && ` | 제목 ${sec.title_max_length}자 이내`}
          {sec.title_min_length && ` | 제목 ${sec.title_min_length}자 이상`}
          {sec.subtitle_max_length && ` | 부제목 ${sec.subtitle_max_length}자 이내`}
          {sec.photo_required ? ` | 사진 필수 (${sec.photo_count}장)` : ''}
          {sec.caption_required ? ' | 캡션 필수' : ''}
        </p>
        {isAlreadySubmitted && (
          <div className="mt-4 bg-white/20 rounded-xl px-4 py-2 inline-block">
            <span className="font-bold">
              {article.status === 'submitted' ? '⏳ 편집장 컨펌 대기 중' : '✅ 컨펌 완료'}
            </span>
          </div>
        )}
      </div>

      <div className="space-y-6">
        {/* 1. 제목 입력란 */}
        {!isHancutDaejin && (
          <div className="bg-white rounded-2xl p-6 border border-gray-100">
            <label className="block text-sm font-bold text-gray-700 mb-2">
              제목
              {sec.title_max_length && (
                <span className="ml-2 text-gray-400 font-normal">({sec.title_max_length}자 이내 권장)</span>
              )}
              {sec.title_min_length && (
                <span className="ml-2 text-gray-400 font-normal">({sec.title_min_length}자 이상 권장)</span>
              )}
            </label>
            <div
              ref={titleRef}
              contentEditable={!isAlreadySubmitted || isAdmin}
              dangerouslySetInnerHTML={{ __html: article?.title || '' }}
              onInput={(e) => handleInput(e, 'title')}
              placeholder="기사 제목을 입력하세요"
              className={`w-full px-4 py-3 rounded-xl border text-lg font-bold min-h-[3rem] outline-none ${
                titleOverMax ? 'border-red-300 bg-red-50' : titleUnderMin ? 'border-yellow-300 bg-yellow-50' : 'border-gray-200'
              } focus:ring-2 focus:ring-[#004b93] focus:border-transparent`}
            />
            <div className="flex justify-between mt-2 text-xs">
              <span className={titleOverMax ? 'text-red-500 font-bold' : titleUnderMin ? 'text-yellow-600 font-bold' : 'text-gray-400'}>
                {titleLen}자
                {titleOverMax && ` (${titleLen - sec.title_max_length}자 초과)`}
                {titleUnderMin && ` (${sec.title_min_length - titleLen}자 부족)`}
              </span>
              {sec.title_max_length && <span className="text-gray-400">최대 {sec.title_max_length}자</span>}
              {sec.title_min_length && !sec.title_max_length && <span className="text-gray-400">최소 {sec.title_min_length}자</span>}
            </div>
          </div>
        )}

        {/* 2. 부제목 입력란 */}
        {sec.has_subtitle === 1 && !isHancutDaejin && (
          <div className="bg-white rounded-2xl p-6 border border-gray-100">
            <label className="block text-sm font-bold text-gray-700 mb-2">
              부제목
              {sec.subtitle_max_length && (
                <span className="ml-2 text-gray-400 font-normal">({sec.subtitle_max_length}자 이내 권장)</span>
              )}
              {sec.subtitle_min_length && (
                <span className="ml-2 text-gray-400 font-normal">({sec.subtitle_min_length}자 이상 권장)</span>
              )}
            </label>
            <div
              ref={subtitleRef}
              contentEditable={!isAlreadySubmitted || isAdmin}
              dangerouslySetInnerHTML={{ __html: article?.subtitle || '' }}
              onInput={(e) => handleInput(e, 'subtitle')}
              placeholder="부제목을 입력하세요"
              className={`w-full px-4 py-3 rounded-xl border min-h-[3rem] outline-none ${
                subtitleOverMax ? 'border-red-300 bg-red-50' : subtitleUnderMin ? 'border-yellow-300 bg-yellow-50' : 'border-gray-200'
              } focus:ring-2 focus:ring-[#004b93] focus:border-transparent`}
            />
            <div className="flex justify-between mt-2 text-xs">
              <span className={subtitleOverMax ? 'text-red-500 font-bold' : subtitleUnderMin ? 'text-yellow-600 font-bold' : 'text-gray-400'}>
                {subtitleLen}자
                {subtitleOverMax && ` (${subtitleLen - sec.subtitle_max_length}자 초과)`}
                {subtitleUnderMin && ` (${sec.subtitle_min_length - subtitleLen}자 부족)`}
              </span>
            </div>
          </div>
        )}

        {/* 3. 사진 첨부란 */}
        <div className="bg-white rounded-2xl p-6 border border-gray-100">
          <label className="block text-sm font-bold text-gray-700 mb-2">
            사진 첨부
            {sec.photo_required === 1 && (
              <span className="ml-2 text-red-500 font-bold">⚠ 사진 첨부 필수</span>
            )}
            {sec.photo_orientation && (
              <span className="ml-2 text-gray-400 font-normal">({sec.photo_orientation} 권장)</span>
            )}
          </label>

          <div className={`grid ${sec.photo_count >= 2 ? 'grid-cols-2' : 'grid-cols-1'} gap-4`}>
            {/* 사진 1 */}
            <div>
              <label className="block w-full h-48 border-2 border-dashed border-gray-300 rounded-xl hover:border-[#004b93] transition cursor-pointer flex flex-col items-center justify-center overflow-hidden">
                {photo1Preview ? (
                  <img src={photo1Preview} alt="사진1" className="w-full h-full object-cover" />
                ) : (
                  <>
                    <i className="fas fa-camera text-2xl text-gray-400 mb-2"></i>
                    <span className="text-sm text-gray-400">사진 1 클릭하여 업로드</span>
                  </>
                )}
                <input type="file" accept="image/*" className="hidden" onChange={(e) => handlePhotoUpload(e, 'photo1')} />
              </label>
            </div>
            {/* 사진 2 (2개 이상일 때) */}
            {sec.photo_count >= 2 && (
              <div>
                <label className="block w-full h-48 border-2 border-dashed border-gray-300 rounded-xl hover:border-[#004b93] transition cursor-pointer flex flex-col items-center justify-center overflow-hidden">
                  {photo2Preview ? (
                    <img src={photo2Preview} alt="사진2" className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <i className="fas fa-camera text-2xl text-gray-400 mb-2"></i>
                      <span className="text-sm text-gray-400">사진 2 클릭하여 업로드</span>
                    </>
                  )}
                  <input type="file" accept="image/*" className="hidden" onChange={(e) => handlePhotoUpload(e, 'photo2')} />
                </label>
              </div>
            )}
          </div>
        </div>

        {/* 4. 캡션 입력란 */}
        <div className="bg-white rounded-2xl p-6 border border-gray-100">
          <label className="block text-sm font-bold text-gray-700 mb-2">
            캡션
            {sec.caption_required === 1 && (
              <span className="ml-2 text-red-500 font-bold">⚠ 캡션 입력 필수</span>
            )}
          </label>
          <div
            ref={caption1Ref}
            contentEditable={!isAlreadySubmitted || isAdmin}
            dangerouslySetInnerHTML={{ __html: article?.caption1 || '' }}
            onInput={(e) => handleInput(e, 'caption1')}
            placeholder="사진 캡션을 입력하세요"
            className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-[#004b93] focus:border-transparent mb-2 outline-none min-h-[3rem]"
          />
          {sec.photo_count >= 2 && (
            <div
              ref={caption2Ref}
              contentEditable={!isAlreadySubmitted || isAdmin}
              dangerouslySetInnerHTML={{ __html: article?.caption2 || '' }}
              onInput={(e) => handleInput(e, 'caption2')}
              placeholder="사진 2 캡션을 입력하세요"
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-[#004b93] focus:border-transparent outline-none min-h-[3rem]"
            />
          )}
        </div>

        {/* 5. 원고 입력란 (한컷대진 제외) */}
        {sec.has_body === 1 && !isHancutDaejin && (
          <div className="bg-white rounded-2xl p-6 border border-gray-100">
            <label className="block text-sm font-bold text-gray-700 mb-2">
              원고 본문
              {sec.volume && (
                <span className="ml-2 text-gray-400 font-normal">(원고지 200자 기준 {sec.volume} 분량)</span>
              )}
            </label>
            <div
              ref={bodyRef}
              contentEditable={!isAlreadySubmitted || isAdmin}
              dangerouslySetInnerHTML={{ __html: article?.body || '' }}
              onInput={(e) => handleInput(e, 'body')}
              placeholder="기사 본문을 작성하세요..."
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-[#004b93] focus:border-transparent outline-none min-h-[20rem] whitespace-pre-wrap leading-relaxed"
            />
            {sec.volume && (
              <div className="mt-3 flex items-center justify-between">
                <div className="flex items-center space-x-4 text-sm">
                  <span className="text-gray-500">
                    현재 분량: <span className="font-bold text-gray-800">{currentVolume}</span>
                  </span>
                  <span className="text-gray-500">
                    목표 분량: <span className="font-bold text-gray-800">{sec.volume}</span>
                  </span>
                </div>
                <div>
                  {Math.abs(volumeDiff) < 0.3 && currentVolume > 0 ? (
                    <span className="text-green-600 text-sm font-bold">
                      <i className="fas fa-check-circle mr-1"></i> 적정 분량
                    </span>
                  ) : volumeDiff > 0 ? (
                    <span className="text-red-500 text-sm font-bold">
                      <i className="fas fa-exclamation-triangle mr-1"></i> {volumeDiff.toFixed(1)} 초과
                    </span>
                  ) : currentVolume > 0 ? (
                    <span className="text-yellow-600 text-sm font-bold">
                      <i className="fas fa-exclamation-triangle mr-1"></i> {Math.abs(volumeDiff).toFixed(1)} 미달
                    </span>
                  ) : null}
                </div>
              </div>
            )}

            {/* 분량 프로그레스 바 */}
            {sec.volume && currentVolume > 0 && (
              <div className="mt-2 w-full bg-gray-200 rounded-full h-2">
                <div
                  className={`h-2 rounded-full transition-all ${
                    Math.abs(volumeDiff) < 0.3 ? 'bg-green-500' :
                    volumeDiff > 0 ? 'bg-red-500' : 'bg-yellow-500'
                  }`}
                  style={{ width: `${Math.min((currentVolume / sec.volume) * 100, 100)}%` }}
                ></div>
              </div>
            )}
          </div>
        )}

        {/* 7. 기자 정보 */}
        <div className="bg-white rounded-2xl p-6 border border-gray-100">
          <label className="block text-sm font-bold text-gray-700 mb-4">기자 정보</label>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-xs text-gray-400 mb-1 block">기자 이름</label>
              <input
                type="text"
                value={reporterName}
                onChange={(e) => setReporterName(e.target.value)}
                placeholder="기자 이름"
                className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-[#004b93] focus:border-transparent"
              />
            </div>
            <div>
              <label className="text-xs text-gray-400 mb-1 block">이메일</label>
              <input
                type="email"
                value={reporterEmail}
                onChange={(e) => setReporterEmail(e.target.value)}
                placeholder="reporter@daejin.ac.kr"
                className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-[#004b93] focus:border-transparent"
              />
            </div>
          </div>
        </div>

        {/* 하단 버튼 */}
        <div className="flex justify-between items-center pt-4 pb-12">
          <button
            onClick={() => navigate(-1)}
            className="px-6 py-3 rounded-2xl font-bold text-gray-500 hover:bg-gray-100 transition"
          >
            돌아가기
          </button>

          <div className="flex space-x-3">
            <button
              onClick={handleSave}
              disabled={saving}
              className="px-6 py-3 rounded-2xl font-bold bg-gray-100 text-gray-700 hover:bg-gray-200 transition disabled:opacity-50"
            >
              {saving ? <i className="fas fa-spinner fa-spin mr-2"></i> : <i className="fas fa-save mr-2"></i>}
              임시 저장
            </button>

            {!isAlreadySubmitted && (
              <button
                onClick={handleSubmitConfirm}
                disabled={submitting || saving}
                className="px-8 py-3 rounded-2xl font-bold bg-[#004b93] text-white hover:bg-[#003a75] transition disabled:opacity-50"
              >
                {submitting ? <i className="fas fa-spinner fa-spin mr-2"></i> : <i className="fas fa-paper-plane mr-2"></i>}
                편집장 컨펌 요청
              </button>
            )}

            {article.status === 'submitted' && (
              <span className="px-8 py-3 rounded-2xl font-bold bg-orange-100 text-orange-700">
                <i className="fas fa-clock mr-2"></i>컨펌 대기 중
              </span>
            )}

            {article.status === 'confirmed' && (
              <span className="px-8 py-3 rounded-2xl font-bold bg-green-100 text-green-700">
                <i className="fas fa-check mr-2"></i>컨펌 완료
              </span>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}

export default ArticleWrite;
